const express = require('express');
const app = express();

// URL: /users/123/books/456
app.get('/users/:userId/books/:bookId', (req, res) => {
  const { userId, bookId } = req.params;
  res.json({
    message: `Fetching book ${bookId} for user ${userId}`,
    userId: userId,
    bookId: bookId
  });
});
